-- 컨텍스트를 본다

@Test
void 관리_여부() {
    em.clear();
    queryFactory.selectFrom(member).fetch();
    SessionImpl s = em.unwrap(SessionImpl.class);
    System.out.println("엔티티 조회 후: " +
            s.getPersistenceContext().getNumberOfManagedEntities());

    em.clear();
    queryFactory.select(member.username).from(member).fetch();
    System.out.println("값 조회 후:     " +
            s.getPersistenceContext().getNumberOfManagedEntities());
}

