-- 고쳐도 안 나간다

@Test
void 수정_불가() {
    em.clear();
    List<String> names = queryFactory
            .select(member.username).from(member)
            .where(member.username.eq("m1")).fetch();

    names.set(0, "바꿈");
    em.flush();
    System.out.println("flush 했는데 update 가 없다");

    em.clear();
    System.out.println("다시 읽으면: " + queryFactory
            .select(member.username).from(member)
            .where(member.id.eq(1L)).fetchOne());
}

