-- 메모리를 잰다

@Test
void 메모리() {
    for (int i = 0; i < 20000; i++) em.persist(new Member("p" + i, i % 50));
    em.flush(); em.clear();

    System.gc();
    long a = used();
    queryFactory.selectFrom(member).fetch();
    System.out.printf("엔티티: %d KB%n", (used() - a) / 1024);

    em.clear();
    System.gc();
    long b = used();
    queryFactory.select(member.username).from(member).fetch();
    System.out.printf("값:     %d KB%n", (used() - b) / 1024);
}

