-- 시간도 다르다

@Test
void 시간() {
    for (String kind : List.of("엔티티", "값")) {
        em.clear();
        long t = System.nanoTime();
        if (kind.equals("엔티티")) queryFactory.selectFrom(member).fetch();
        else queryFactory.select(member.username).from(member).fetch();
        System.out.printf("%-6s %d ms%n", kind,
                (System.nanoTime() - t) / 1_000_000);
    }
}

