-- null 이 섞인다

@Test
void null_섞임() {
    em.clear();
    List<String> teamNames = queryFactory
            .select(team.name)
            .from(member)
            .leftJoin(member.team, team)
            .fetch();
    System.out.println("건수: " + teamNames.size());
    System.out.println("null: " +
            teamNames.stream().filter(Objects::isNull).count());
}

