-- distinct 를 쓴다

@Test
void distinct() {
    em.clear();
    System.out.println("그냥:     " + queryFactory
            .select(member.age).from(member).fetch().size());

    em.clear();
    List<Integer> ages = queryFactory
            .select(member.age).distinct().from(member).fetch();
    System.out.println("distinct: " + ages.size() + " " + ages);
}

